let _db = 'ContosoCare';
let _t1 = 'sqlvm01';
let _t2 = 'arcsql01';
let _t3prefix = 'azuresql01-';
let _t3suffix = '/ContosoCare';
let _target = (resourceType: string, resourceName: string) {
    case(resourceType == 'virtualMachines' and resourceName =~ _t1, 'T1',
         resourceType == 'machines' and resourceName =~ _t2, 'T2',
         resourceType == 'servers/databases' and resourceName startswith _t3prefix and resourceName endswith _t3suffix, 'T3',
         '')
};
union withsource=TableName SqlServer*
| where SampleTimeUTC between (_start .. _end)
| where ResourceGroup =~ _rg
| extend Target = _target(ResourceType, ResourceName)
| where isnotempty(Target)
| summarize Rows = count(), Tables = dcount(TableName), LastSampleUTC = max(SampleTimeUTC), Instances = dcount(SqlServerInstanceName)
        by Target, ResourceType, ResourceName
| order by Target asc
| where isempty(_selectedTargets) or Target in (_selectedTargets)
| extend MinutesSinceLastSample = round((now() - LastSampleUTC) / 1m, 1)
| join kind=rightouter (datatable(Target: string) ['T1', 'T2', 'T3'] | where isempty(_selectedTargets) or Target in (_selectedTargets)) on Target
| extend Target = iff(isempty(Target), Target1, Target)
| extend State = case(isnull(LastSampleUTC), 'No data', MinutesSinceLastSample <= 15, 'Fresh', 'Stale'),
         Freshness = iff(isnull(LastSampleUTC), 'no data in range', strcat(tostring(MinutesSinceLastSample), ' min ago'))
| project Target, State, Freshness, Resource = ResourceName, ResourceType, Tables, Rows, Instances, LastSampleUTC, MinutesSinceLastSample
| order by Target asc

